from unittest.mock import patch, mock_open
import io
import sys
import проверка_лицензий


class TestПроверкаЛицензий(unittest.TestCase):
    def setUp(self):
        self.allowed = {'MIT', 'BSD-3-Clause', 'Apache-2.0', 'Public Domain', 'Проприетарная'}

    @patch('проверка_лицензий.open', new_callable=mock_open, read_data='Компонент;Лицензия\nA;MIT\nB;GPL\n')
    @patch('sys.stdout', new_callable=io.StringIO)
    def test_mixed_licenses(self, mock_stdout, mock_file):
        проверка_лицензий.main()
        output = mock_stdout.getvalue()
        self.assertIn('A — MIT — допустима', output)
        self.assertIn('B — GPL — требует проверки', output)
        self.assertIn('Итого: допустимо — 1, требует проверки — 1', output)

    @patch('проверка_лицензий.open', new_callable=mock_open, read_data='Компонент;Лицензия\nC;Apache-2.0\nD;BSD-3-Clause\n')
    @patch('sys.stdout', new_callable=io.StringIO)
    def test_all_allowed(self, mock_stdout, mock_file):
        проверка_лицензий.main()
        output = mock_stdout.getvalue()
        self.assertIn('C — Apache-2.0 — допустима', output)
        self.assertIn('D — BSD-3-Clause — допустима', output)
        self.assertIn('Итого: допустимо — 2, требует проверки — 0', output)

    @patch('проверка_лицензий.open', new_callable=mock_open, read_data='Компонент;Лицензия\nE;X\nF;Y\n')
    @patch('sys.stdout', new_callable=io.StringIO)
    def test_all_need_review(self, mock_stdout, mock_file):
        проверка_лицензий.main()
        output = mock_stdout.getvalue()
        self.assertIn('E — X — требует проверки', output)
        self.assertIn('F — Y — требует проверки', output)
        self.assertIn('Итого: допустимо — 0, требует проверки — 2', output)


if __name__ == '__main__':
